#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Pack the reviewed 40x40 user-reference pixel grids, with no resampling at runtime."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
data = json.loads((ROOT / 'assets/snow-icons.json').read_text())['sprites'][5:]  # retain CH and the four approved generator motifs only
lines = ['/* SPDX-License-Identifier: GPL-3.0-only */',
         '/* Generated by tools/gen_snow_icons.py; shared rows preserve exact pixels. */']
unique = list(dict.fromkeys(r for s in data for r in s['rows']))
assert len(unique) <= 256
lines.append(f'static const uint8_t SN_SPRITE_ROWS[{len(unique)}][5]={{')
for row in unique:
    b = [sum(1 << (7-i) for i in range(8) if row[n*8+i] == '#') for n in range(5)]
    lines.append(' {' + ','.join(f'0x{v:02x}' for v in b) + '},')
lines.append('};')
lines.append('static const uint8_t SN_SPRITE_INDEX[5][40]={')
assert len(data) == 5
for sprite in data:
    rows = sprite['rows']
    assert len(rows) == 40 and all(len(r) == 40 and set(r) <= {'.', '#'} for r in rows)
    lines.append(' /* ' + sprite['name'] + ' */ {' + ','.join(str(unique.index(r)) for r in rows) + '},')
lines.append('};')
(ROOT / 'firmware/src/snow_icons.h').write_text('\n'.join(lines) + '\n')
